// ---------------------------------------------------------------- procedural textures (visual only, fixed seeds)
function makeCanvas(w, h) { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; }
function grain(ctx, w, h, amp, rng) {
  const img = ctx.getImageData(0, 0, w, h), d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (rng() - 0.5) * amp;
    d[i] = clamp(d[i] + n, 0, 255); d[i + 1] = clamp(d[i + 1] + n, 0, 255); d[i + 2] = clamp(d[i + 2] + n, 0, 255);
  }
  ctx.putImageData(img, 0, 0);
}
function canvasTex(c, repeatX = 1, repeatY = 1, srgb = true) {
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(repeatX, repeatY);
  t.anisotropy = maxAniso; if (srgb) t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
function makeTileTex(base, amp, seed, size, decorate) {
  const c = makeCanvas(size, size), ctx = c.getContext('2d'), rng = mulberry32(seed);
  ctx.fillStyle = base; ctx.fillRect(0, 0, size, size);
  if (decorate) decorate(ctx, rng, size);
  grain(ctx, size, size, amp, rng);
  return c;
}
const grassCanvas = makeTileTex('#4f6a2b', 46, 11, 512, (ctx, rng, n) => {
  for (let i = 0; i < 900; i++) { ctx.fillStyle = `rgba(${40 + rng() * 40},${70 + rng() * 50},${20 + rng() * 20},0.35)`; const r = 6 + rng() * 26; ctx.beginPath(); ctx.ellipse(rng() * n, rng() * n, r, r * 0.6, rng() * 3, 0, 6.3); ctx.fill(); }
});
const gravelCanvas = makeTileTex('#8f8779', 70, 12, 512, (ctx, rng, n) => {
  for (let i = 0; i < 2500; i++) { const g = 110 + rng() * 90; ctx.fillStyle = `rgb(${g},${g - 6},${g - 14})`; ctx.beginPath(); ctx.arc(rng() * n, rng() * n, 1 + rng() * 3, 0, 6.3); ctx.fill(); }
});
const brickCanvas = (() => {
  const w = 256, h = 128, c = makeCanvas(w, h), ctx = c.getContext('2d'), rng = mulberry32(21);
  ctx.fillStyle = '#b8ae9c'; ctx.fillRect(0, 0, w, h);           // mortar
  ctx.fillStyle = '#9a4b34'; ctx.fillRect(5, 5, w - 10, h - 10); // clay face
  for (let i = 0; i < 220; i++) { ctx.fillStyle = `rgba(${60 + rng() * 60},${20 + rng() * 25},${10 + rng() * 20},${0.12 + rng() * 0.25})`; ctx.beginPath(); ctx.arc(5 + rng() * (w - 10), 5 + rng() * (h - 10), 2 + rng() * 9, 0, 6.3); ctx.fill(); }
  for (let i = 0; i < 40; i++) { ctx.fillStyle = `rgba(230,200,170,${0.05 + rng() * 0.12})`; ctx.fillRect(5 + rng() * (w - 14), 5 + rng() * (h - 14), 3 + rng() * 10, 1 + rng() * 3); }
  grain(ctx, w, h, 34, rng);
  return c;
})();
const curbCanvas = (() => {
  const c = makeCanvas(256, 64), ctx = c.getContext('2d'), rng = mulberry32(5);
  ctx.fillStyle = '#c92c2c'; ctx.fillRect(0, 0, 128, 64); ctx.fillStyle = '#e9e6dd'; ctx.fillRect(128, 0, 128, 64);
  grain(ctx, 256, 64, 26, rng); return c;
})();
const asphaltCache = new Map();
function asphaltTexture(x0, x1, carX0, wallX) {
  const key = `${x0}|${x1}|${carX0}|${wallX}`;
  if (asphaltCache.has(key)) return asphaltCache.get(key);
  const W = 4096, len = x1 - x0, H = Math.round(W * 8 / len), ppm = W / len, ppmZ = H / 8;
  const c = makeCanvas(W, H), ctx = c.getContext('2d'), rng = mulberry32(77);
  const X = (x) => (x - x0) * ppm, Z = (z) => (z + 4) * ppmZ;
  ctx.fillStyle = '#3b3d40'; ctx.fillRect(0, 0, W, H);
  for (let i = 0; i < 6000; i++) { const g = 40 + rng() * 60; ctx.fillStyle = `rgba(${g},${g},${g + 4},${0.2 + rng() * 0.4})`; ctx.fillRect(rng() * W, rng() * H, 1 + rng() * 4, 1 + rng() * 3); }
  // lane wear
  for (const lz of [-2.0, 2.0]) for (const dz of [-0.75, 0.75]) { const g = ctx.createLinearGradient(0, Z(lz + dz - 0.35), 0, Z(lz + dz + 0.35)); g.addColorStop(0, 'rgba(0,0,0,0)'); g.addColorStop(0.5, 'rgba(0,0,0,0.16)'); g.addColorStop(1, 'rgba(0,0,0,0)'); ctx.fillStyle = g; ctx.fillRect(0, Z(lz + dz - 0.35), W, 0.7 * ppmZ); }
  // markings
  ctx.fillStyle = 'rgba(236,236,230,0.92)';
  ctx.fillRect(0, Z(-3.82), W, 0.14 * ppmZ); ctx.fillRect(0, Z(3.68), W, 0.14 * ppmZ);
  for (let x = x0 + 1; x < x1; x += 6) ctx.fillRect(X(x), Z(-0.07), 3 * ppm, 0.14 * ppmZ);
  // start grid boxes
  ctx.lineWidth = 0.12 * ppm; ctx.strokeStyle = 'rgba(236,236,230,0.9)';
  for (let i = 0; i < 4; i++) { const gx = carX0 - 2.1 - i * 4.6, gz = (i % 2 ? 1 : -1) * 2.0; ctx.strokeRect(X(gx), Z(gz - 1.05), 4.2 * ppm, 2.1 * ppmZ); }
  // start line checker
  const sq = 0.4; for (let i = 0; i < 2; i++) for (let j = 0; j < 20; j++) { ctx.fillStyle = (i + j) % 2 ? '#e8e6de' : '#151515'; ctx.fillRect(X(carX0 + 2.3 + i * sq), Z(-4 + j * sq), sq * ppm + 1, sq * ppmZ + 1); }
  // impact line
  ctx.fillStyle = 'rgba(240,200,60,0.85)'; for (let z = -3.6; z < 3.6; z += 0.8) ctx.fillRect(X(wallX - 1.4), Z(z), 0.16 * ppm, 0.45 * ppmZ);
  // old rubber
  for (let i = 0; i < 26; i++) { ctx.fillStyle = `rgba(10,10,12,${0.08 + rng() * 0.16})`; const sx = X(x0 + rng() * len), sz = Z(-3 + rng() * 6); ctx.fillRect(sx, sz, (2 + rng() * 8) * ppm, 0.24 * ppmZ); }
  grain(ctx, W, H, 22, rng);
  const t = canvasTex(c, 1, 1); t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping;
  asphaltCache.set(key, t); return t;
}

// ---------------------------------------------------------------- materials
const brickMap = canvasTex(brickCanvas, 1, 1);
const MAT = {
  paint: new THREE.MeshPhysicalMaterial({ color: 0x1d55cf, metalness: 0.72, roughness: 0.3, clearcoat: 1.0, clearcoatRoughness: 0.06, envMapIntensity: 1.25 }),
  trim: new THREE.MeshStandardMaterial({ color: 0x14161a, roughness: 0.6, metalness: 0.25 }),
  chrome: new THREE.MeshStandardMaterial({ color: 0xe2e6ea, roughness: 0.12, metalness: 1.0 }),
