// ---------------------------------------------------------------- collision groups
const GRP = { ENV: 1, CAR: 2, DEBRIS: 4, BRICK: 8 };
const ALL = GRP.ENV | GRP.CAR | GRP.DEBRIS | GRP.BRICK;
const groups = (member, filter) => ((member & 0xffff) << 16) | (filter & 0xffff);
const GROUP_ENV = groups(GRP.ENV, ALL);
const GROUP_CAR = groups(GRP.CAR, GRP.ENV | GRP.DEBRIS | GRP.BRICK); // attached parts ignore each other
const GROUP_DEBRIS = groups(GRP.DEBRIS, ALL);
const GROUP_BRICK = groups(GRP.BRICK, ALL);

// ---------------------------------------------------------------- environment (track, curbs, barriers, lights)
let envGroup = null;
function staticBox(world, cx, cy, cz, hx, hy, hz, friction, restitution = 0.1) {
  const body = world.createRigidBody(RAPIER.RigidBodyDesc.fixed().setTranslation(cx, cy, cz));
  const col = world.createCollider(RAPIER.ColliderDesc.cuboid(hx, hy, hz).setFriction(friction).setRestitution(restitution).setCollisionGroups(GROUP_ENV), body);
  return col;
}
function buildEnvironment(world, s, carX0, wallX) {
  const g = new THREE.Group(); envGroup = g; scene.add(g);
  const L = s.trackLength, x0 = -L / 2 - 4, x1 = L / 2 + 6, len = x1 - x0, cx = (x0 + x1) / 2;
  const mesh = (geo, mat, x, y, z, cast = false, recv = true) => { const m = new THREE.Mesh(geo, mat); m.position.set(x, y, z); m.castShadow = cast; m.receiveShadow = recv; g.add(m); return m; };
  const grass = mesh(new THREE.PlaneGeometry(700, 700), MAT.grass, 0, -0.012, 0); grass.rotation.x = -Math.PI / 2;
  for (const side of [-1, 1]) { const gr = mesh(new THREE.PlaneGeometry(len + 6, 1.9), MAT.gravel, cx, -0.004, side * 5.4); gr.rotation.x = -Math.PI / 2; }
  const asphalt = mesh(new THREE.PlaneGeometry(len, 8), new THREE.MeshStandardMaterial({ map: asphaltTexture(x0, x1, carX0, wallX), bumpMap: asphaltTexture(x0, x1, carX0, wallX), bumpScale: 0.004, roughness: 0.93, metalness: 0.0 }), cx, 0.0, 0);
  asphalt.rotation.x = -Math.PI / 2;
  for (const side of [-1, 1]) {
    mesh(new THREE.BoxGeometry(len, 0.07, 0.45), MAT.curb, cx, 0.035, side * 4.225, true);
    staticBox(world, cx, 0.035, side * 4.225, len / 2, 0.035, 0.225, 0.8);
    mesh(new THREE.BoxGeometry(len + 4, 0.32, 0.06), MAT.armco, cx, 0.62, side * 6.6, true);
    mesh(new THREE.BoxGeometry(len + 4, 0.06, 0.06), MAT.armco, cx, 0.28, side * 6.6, true);
    staticBox(world, cx, 0.45, side * 6.6, len / 2 + 2, 0.4, 0.04, 0.6);
    const n = Math.floor((len + 4) / 2), posts = new THREE.InstancedMesh(new THREE.BoxGeometry(0.1, 0.78, 0.1), MAT.pole, n);
    posts.castShadow = true; const M = new THREE.Matrix4();
    for (let i = 0; i < n; i++) { M.makeTranslation(x0 - 2 + 1 + i * 2, 0.39, side * 6.66); posts.setMatrixAt(i, M); }
    g.add(posts);
  }
  for (let i = 0; i < 6; i++) {
    const px = x0 + 2 + i * (len - 4) / 5, side = i % 2 ? 1 : -1;
    const pole = mesh(new THREE.CylinderGeometry(0.07, 0.11, 9.5, 12), MAT.pole, px, 4.75, side * 8.4, true, false);
    const arm = mesh(new THREE.BoxGeometry(0.16, 0.16, 2.4), MAT.pole, px, 9.35, side * 7.3, true, false);
    mesh(new THREE.BoxGeometry(0.9, 0.18, 0.5), MAT.lamp, px, 9.3, side * 6.2, true, false);
    void pole; void arm;
  }
  // distant treeline for horizon depth (no shadows)
  const trees = new THREE.InstancedMesh(new THREE.ConeGeometry(2.6, 8, 6), MAT.tree, 140), rng = mulberry32(99), M = new THREE.Matrix4(), col = new THREE.Color();
  for (let i = 0; i < 140; i++) {
    const a = (i / 140) * Math.PI * 2, r = 120 + rng() * 60, sc = 0.8 + rng() * 0.9;
    M.compose(V3(Math.cos(a) * r, 4 * sc, Math.sin(a) * r), new THREE.Quaternion(), V3(sc, sc, sc)); trees.setMatrixAt(i, M);
    col.setHSL(0.28 + rng() * 0.06, 0.35, 0.16 + rng() * 0.12); trees.setColorAt(i, col);
  }
  g.add(trees);
  // physics ground
  const ground = world.createRigidBody(RAPIER.RigidBodyDesc.fixed().setTranslation(0, -1, 0));
  const gcol = world.createCollider(RAPIER.ColliderDesc.cuboid(400, 1, 400).setFriction(s.groundFriction).setRestitution(0.05).setCollisionGroups(GROUP_ENV), ground);
  fitShadowToBox(x0 - 1, x1 + 2, -8.5, 8.5, 4.5);
  return { groundHandle: gcol.handle };
}

// ---------------------------------------------------------------- car definition (car-local: +x forward, y up from ground, z lateral)
function buildCarDef(s) {
  const sx = s.carLength / 4.2, sy = s.carHeight / 1.45, sz = s.carWidth / 1.8;
  const P = (x, y, z) => [x * sx, y * sy, z * sz];
  const S = (w, h, d) => [w * sx, h * sy, d * sz];
  const R = 0.33 * Math.min(sx, sy), HW = 0.12 * sz, mScale = s.carMass / 1250;
  const parts = [], joints = [];
  const part = (name, pos, opts = {}) => { const p = { name, pos: P(...pos), colliders: [], mat: 'paint', fBreak: Infinity, extras: null, ...opts }; parts.push(p); return p; };
  const box = (p, c, size, mass, extra = {}) => p.colliders.push({ type: 'box', c: P(...c), s: S(...size), mass: mass * mScale, q: null, mat: p.mat, ...extra });
  const raked = (p, a, b, zc, zLen, t, mass, extra = {}) => {
    const ax = a[0] * sx, ay = a[1] * sy, bx = b[0] * sx, by = b[1] * sy;
    const len = Math.hypot(bx - ax, by - ay), ang = Math.atan2(by - ay, bx - ax) * 180 / Math.PI;
    p.colliders.push({ type: 'box', c: [(ax + bx) / 2, (ay + by) / 2, zc * sz], s: [len, t, zLen * sz], mass: mass * mScale, q: qZ(ang), mat: p.mat, ...extra });
  };
  const joint = (a, b, pt, gBreak, fBreak, type = 'fixed', axis = null) => joints.push({ a, b, pt: P(...pt), gBreak, fBreak, type, axis });

  // cabin: tub + roof + pillars (one rigid body, compound collider)
  const cabin = part('cabin', [-0.55, 0.61, 0], { extras: 'cabin' });
  box(cabin, [-0.55, 0.61, 0], [2.9, 0.62, 1.66], 410, { round: 0.06 });
  box(cabin, [-0.35, 1.43, 0], [1.3, 0.04, 1.5], 54, { round: 0.015 });
  for (const zs of [-1, 1]) {
    box(cabin, [-0.27, 1.165, zs * 0.80], [0.06, 0.49, 0.05], 6, { mat: 'trim' });
    raked(cabin, [0.9, 0.93], [0.3, 1.40], zs * 0.73, 0.06, 0.06, 6, { mat: 'trim' });
    raked(cabin, [-1.5, 0.99], [-1.0, 1.40], zs * 0.73, 0.06, 0.06, 6, { mat: 'trim' });
  }
  const bay = part('engineBay', [1.2, 0.6, 0], { mat: 'under' });
  box(bay, [1.2, 0.33, 0], [0.58, 0.06, 1.5], 40);
  box(bay, [1.2, 0.63, 0.685], [0.58, 0.54, 0.13], 35);
  box(bay, [1.2, 0.63, -0.685], [0.58, 0.54, 0.13], 35);
  box(bay, [0.93, 0.63, 0], [0.04, 0.54, 1.24], 20);
  const engine = part('engine', [1.22, 0.62, 0], { mat: 'engine', extras: 'engine' });
  box(engine, [1.22, 0.62, 0], [0.46, 0.46, 0.6], 200, { round: 0.03 });
  const nose = part('nose', [1.75, 0.55, 0], { extras: 'nose' });
  box(nose, [1.75, 0.55, 0], [0.49, 0.5, 1.4], 70, { round: 0.05 });
  const fb = part('frontBumper', [2.06, 0.48, 0], { extras: 'frontBumper' });
  box(fb, [2.06, 0.48, 0], [0.11, 0.36, 1.78], 12, { round: 0.04 });
  const rb = part('rearBumper', [-2.065, 0.5, 0]);
  box(rb, [-2.065, 0.5, 0], [0.11, 0.34, 1.78], 12, { round: 0.04 });
  const hood = part('hood', [1.465, 0.925, 0]);
  box(hood, [1.465, 0.925, 0], [1.03, 0.04, 1.52], 18, { round: 0.015 });
  const trunk = part('trunk', [-1.75, 0.95, 0]);
  box(trunk, [-1.75, 0.95, 0], [0.49, 0.04, 1.5], 16, { round: 0.015 });
  for (const zs of [-1, 1]) {
    const side = zs > 0 ? 'L' : 'R';
    const f = part('fender' + side, [1.455, 0.675, zs * 0.855]);
    box(f, [1.455, 0.675, zs * 0.855], [1.09, 0.45, 0.04], 14, { round: 0.015 });
    const dF = part('doorF' + side, [0.32, 0.62, zs * 0.875], { extras: 'door' });
    box(dF, [0.32, 0.62, zs * 0.875], [1.08, 0.60, 0.05], 32, { round: 0.02 });
    const dR = part('doorR' + side, [-0.80, 0.62, zs * 0.875], { extras: 'door' });
    box(dR, [-0.80, 0.62, zs * 0.875], [1.0, 0.60, 0.05], 32, { round: 0.02 });
    // frameless side glass: trapezoids following the pillar rake (convex hull colliders)
    const gF = part('glassF' + side, [0.25, 1.16, zs * 0.86], { mat: 'glass', glass: true, fBreak: 1200 });
    gF.colliders.push({ type: 'hull', poly: [[-0.18, 0.94], [0.86, 0.94], [0.36, 1.38], [-0.18, 1.38]].map(([x, y]) => [x * sx, y * sy]), z: zs * 0.86 * sz, t: 0.008, mass: 4 * mScale, mat: 'glass' });
    const gR = part('glassR' + side, [-0.78, 1.16, zs * 0.86], { mat: 'glass', glass: true, fBreak: 1200 });
    gR.colliders.push({ type: 'hull', poly: [[-1.26, 0.94], [-0.34, 0.94], [-0.34, 1.38], [-1.02, 1.38]].map(([x, y]) => [x * sx, y * sy]), z: zs * 0.86 * sz, t: 0.008, mass: 4 * mScale, mat: 'glass' });
    joint('fender' + side, 'engineBay', [1.3, 0.7, zs * 0.84], 12, 7000);
    joint('doorF' + side, 'cabin', [0.85, 0.62, zs * 0.875], 24, 45000, 'revolute', [0, 1, 0]);
    joint('doorF' + side, 'cabin', [-0.2, 0.62, zs * 0.875], 8, 14000);
    joint('doorR' + side, 'cabin', [-0.31, 0.62, zs * 0.875], 26, 45000, 'revolute', [0, 1, 0]);
    joint('doorR' + side, 'cabin', [-1.28, 0.62, zs * 0.875], 9, 14000);
    joint('glassF' + side, 'doorF' + side, [0.25, 1.0, zs * 0.86], 9, 1200);
    joint('glassR' + side, 'doorR' + side, [-0.78, 1.0, zs * 0.86], 9, 1200);
  }
  const ws = part('windshield', [0.6, 1.165, 0], { mat: 'glass', glass: true, fBreak: 1500 });
  raked(ws, [0.9, 0.93], [0.3, 1.40], 0, 1.36, 0.012, 14);
  const rg = part('rearGlass', [-1.25, 1.195, 0], { mat: 'glass', glass: true, fBreak: 1500 });
  raked(rg, [-1.5, 0.99], [-1.0, 1.40], 0, 1.36, 0.012, 10);
  const wheelDefs = [['wheelFL', 1.3, 0.70, 'engineBay', 18], ['wheelFR', 1.3, -0.70, 'engineBay', 18], ['wheelRL', -1.4, 0.70, 'cabin', 28], ['wheelRR', -1.4, -0.70, 'cabin', 28]];
  for (const [name, x, z, parent, gB] of wheelDefs) {
    const w = part(name, [x, 0, z], { wheel: true, mat: 'rubber', extras: 'wheel' });
    w.pos[1] = R;
