    joints.push({ a: name, b: parent, pt: [x * sx, R, z * sz], gBreak: gB, fBreak: parent === 'cabin' ? 90000 : 60000, type: 'fixed', axis: null });
  }
  joint('engineBay', 'cabin', [0.9, 0.6, 0], 30, 220000);
  joint('nose', 'engineBay', [1.5, 0.55, 0], 24, 110000);
  joint('engine', 'engineBay', [1.22, 0.4, 0], 26, 90000);
  joint('frontBumper', 'nose', [2.0, 0.48, 0], 14, 9000);
  joint('rearBumper', 'cabin', [-2.01, 0.5, 0], 24, 40000);
  joint('hood', 'engineBay', [0.96, 0.905, 0], 26, 30000, 'revolute', [0, 0, 1]);
  joint('hood', 'engineBay', [1.96, 0.925, 0], 9, 12000);
  joint('trunk', 'cabin', [-1.51, 0.95, 0], 30, 40000, 'revolute', [0, 0, 1]);
  joint('trunk', 'cabin', [-1.98, 0.95, 0], 12, 30000);
  joint('windshield', 'cabin', [0.6, 1.165, 0], 7, 1500);
  joint('rearGlass', 'cabin', [-1.25, 1.195, 0], 8, 1500);
  return { parts, joints, R, HW, sx, sy, sz };
}

