// ---------------------------------------------------------------- one fixed physics step
function physicsStep() {
  const { world, dt } = sim, g = settings.gravity;
  const cabin = sim.partByName.get('cabin');
  cabin.body.resetForces(true);
  if (sim.driving) {
    const v = cabin.body.linvel().x;
    const aCmd = clamp((sim.vTarget - v) * 6, -sim.aMax, sim.aMax);
    cabin.body.addForce({ x: aCmd * sim.carMassTotal, y: 0, z: 0 }, true);
  }
  for (const p of sim.parts) p.contactF = 0;
  world.step(sim.events);
  sim.t += dt;
  sim.events.drainContactForceEvents((ev) => {
    const h1 = ev.collider1(), h2 = ev.collider2(), F = ev.totalForceMagnitude();
    const i1 = sim.colInfo.get(h1), i2 = sim.colInfo.get(h2);
    if (!i1 || !i2) return;
    if (i1.kind === 'part') i1.ref.contactF = Math.max(i1.ref.contactF, F);
    if (i2.kind === 'part') i2.ref.contactF = Math.max(i2.ref.contactF, F);
    const kinds = i1.kind + '|' + i2.kind;
    if (sim.impactT < 0 && /part/.test(kinds) && /brick/.test(kinds)) onImpact();
    if (sim.fx.length < 24 && F > 1800) {
      const c = world.getCollider(h1); if (!c) return; const pos = c.translation();
      sim.fx.push({ x: pos.x, y: pos.y, z: pos.z, F, metal: /part|shard/.test(kinds), brick: /brick/.test(kinds) });
    }
