    const v = p.body.linvel();
    const ax = (v.x - p.pv.x) / dt, ay = (v.y - p.pv.y) / dt + g, az = (v.z - p.pv.z) / dt;
    p.aEst = Math.hypot(ax, ay, az) / G_REF;
    p.pv.x = v.x; p.pv.y = v.y; p.pv.z = v.z;
  }
  for (const j of sim.joints) {
    if (!j.alive) continue;
    const light = j.a.mass <= j.b.mass ? j.a : j.b;
    if (light.aEst > j.gBreak || Math.max(j.a.contactF, j.b.contactF) > j.fBreak) breakJoint(j);
