    const midX = (cabT.x + wallX) / 2, halfSpan = (wallX - cabT.x) / 2 + 5.5, D = halfSpan / Math.tan(hfov / 2);
    estTgt.set(midX, 1.0, 0); estPos.copy(estTgt).addScaledVector(dirEst, D);
    midPos.set(wallX - 17, 5.0, 17);
